@Test
public void testReadMultipleFilesWithSingleBufferPool() throws Exception {
    // Setup
    BufferFileWriter[] writers = new BufferFileWriter[] { createWriterAndWriteBuffers(ioManager, writerBufferPool, 512), createWriterAndWriteBuffers(ioManager, writerBufferPool, 512) };
    final ResultSubpartitionView[] readers = new ResultSubpartitionView[writers.length];
    // Make this buffer pool small so that we can test the behaviour of the asynchronous view
    // with few  buffers.
    final BufferProvider inputBuffers = new TestPooledBufferProvider(2);
    final ResultSubpartition parent = mock(ResultSubpartition.class);
    try {
        // Wait for writers to finish
        for (BufferFileWriter writer : writers) {
            writer.close();
        }
        // Create the views depending on the test configuration
        for (int i = 0; i < readers.length; i++) {
            if (ioMode.isSynchronous()) {
                readers[i] = new SpilledSubpartitionViewSyncIO(parent, inputBuffers.getMemorySegmentSize(), writers[i].getChannelID(), 0);
            } else {
                // For the asynchronous view, it is important that a registered listener will
                // eventually be notified even if the view never got a buffer to read data into.
                //
                // At runtime, multiple threads never share the same buffer pool as in test. We
                // do it here to provoke the erroneous behaviour.
                readers[i] = new SpilledSubpartitionViewAsyncIO(parent, inputBuffers, ioManager, writers[i].getChannelID(), 0);
            }
        }
        final List<Future<Boolean>> results = Lists.newArrayList();
        // Submit the consuming tasks
        for (ResultSubpartitionView view : readers) {
            results.add(executor.submit(new TestSubpartitionConsumer(view, false, new RecyclingCallback())));
        }
        // Wait for the results
        for (Future<Boolean> res : results) {
            try {
                res.get(2, TimeUnit.MINUTES);
            } catch (TimeoutException e) {
                throw new TimeoutException("There has been a timeout in the test. This " + "indicates that there is a bug/deadlock in the tested subpartition " + "view. The timed out test was in " + ioMode + " mode.");
            }
        }
    } finally {
        for (BufferFileWriter writer : writers) {
            if (writer != null) {
                writer.deleteChannel();
            }
        }
        for (ResultSubpartitionView reader : readers) {
            if (reader != null) {
                reader.releaseAllResources();
            }
        }
    }
}

@Test
public void multiThreaded() throws InterruptedException {
    BlockingQueue<Integer> dataChannel = new ArrayBlockingQueue<Integer>(1);
    List<String> actionLog = Lists.newArrayList();
    SerializedUpdateBuffer buffer = Mockito.mock(SerializedUpdateBuffer.class);
    BlockingBackChannel channel = new BlockingBackChannel(buffer);
    Thread head = new Thread(new IterationHead(channel, dataChannel, actionLog));
    Thread tail = new Thread(new IterationTail(channel, dataChannel, actionLog));
    tail.start();
    head.start();
    head.join();
    tail.join();
    //		int action = 0;
    //		for (String log : actionLog) {
    //			System.out.println("ACTION " + (++action) + ": " + log);
    //		}
    assertEquals(12, actionLog.size());
    assertEquals("head sends data", actionLog.get(0));
    assertEquals("tail receives data", actionLog.get(1));
    assertEquals("tail writes in iteration 0", actionLog.get(2));
    assertEquals("head reads in iteration 0", actionLog.get(3));
    assertEquals("head sends data", actionLog.get(4));
    assertEquals("tail receives data", actionLog.get(5));
    assertEquals("tail writes in iteration 1", actionLog.get(6));
    assertEquals("head reads in iteration 1", actionLog.get(7));
    assertEquals("head sends data", actionLog.get(8));
    assertEquals("tail receives data", actionLog.get(9));
    assertEquals("tail writes in iteration 2", actionLog.get(10));
    assertEquals("head reads in iteration 2", actionLog.get(11));
}

